import React from 'react';
import { useEffect, useState } from 'react';
import { getAllWarehouses } from '../data/dataFetching';

function WarehousesList() {

    const [warehouseList, setWarehouse] = useState([]);
       
    useEffect(() => {
        getAllWarehouses().then(data => setWarehouse(data));
    }, []);

    return (
        <div className='warehouses-list-container'>
            <h1>Warehouses</h1>

            <div className="table-container">
                <table>
                    <thead>
                        <tr>
                        <th>Warehouse ID</th>
                        <th>Name</th>
                        <th>Address</th>
                        </tr>
                    </thead>

                    <tbody>
                        {warehouseList.map(warehouse => (
                    
                        <tr>
                            <td>{warehouse.warehouse_id}</td>
                            <td><a href={'/warehouses/warehouse-info/' + warehouse.warehouse_id}>{warehouse.warehouse_name}</a></td>
                            <td>{warehouse.address}</td>
                        </tr>
                        
                        ))}
                    </tbody>
                </table>

        </div>
        </div>
    )
}

export default WarehousesList;
